        return null;
    }
    if (nextByte >= numBytes) {
        nextByte = 0;
        numBytes = in.read(fileBuffer);
        atEof = numBytes < 1;
        if (atEof) {
            return null;
        }
    }
    // Assuming each "file" entry is prefixed with its size as an integer
    int fileSize = ((fileBuffer[nextByte++] & 0xFF) << 24) |
                   ((fileBuffer[nextByte++] & 0xFF) << 16) |
                   ((fileBuffer[nextByte++] & 0xFF) << 8) |
                    (fileBuffer[nextByte++] & 0xFF);

    if (numBytes - nextByte < fileSize) {
        byte[] fileData = new byte[fileSize];
        int bytesRead = 0;
        while (bytesRead < fileSize) {
            if (nextByte >= numBytes) {
                nextByte = 0;
                numBytes = in.read(fileBuffer);
                if (numBytes < 1) {
                    atEof = true;
                    throw new IOException("Unexpected end of stream");
                }
            }
            int bytesToCopy = Math.min(numBytes - nextByte, fileSize - bytesRead);
            System.arraycopy(fileBuffer, nextByte, fileData, bytesRead, bytesToCopy);
            nextByte += bytesToCopy;
            bytesRead += bytesToCopy;
        }
        return new ByteArrayInputStream(fileData);
    } else {
        InputStream fileStream = new ByteArrayInputStream(fileBuffer, nextByte, fileSize);
        nextByte += fileSize;
        return fileStream;
