public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder output = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char currentChar = str.charAt(i);
        if (currentChar == '\\') {
            // Check if this is the last character, or if the next character is not an escape sequence
            if (i + 1 >= length) {
                output.append(currentChar);
                continue;
            }
            char nextChar = str.charAt(i + 1);
            i++; // Move to the next character as we are processing the escape sequence
            switch (nextChar) {
                case 'b':
                    output.append('\b');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'n':
                    output.append('\n');
                    break;
                case 'f':
                    output.append('\f');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case '"':
                    output.append('\"');
                    break;
                case '\'':
                    output.append('\'');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                case 'u': // Unicode escape
                    if (i + 4 >= length) {
                        throw new Exception("Malformed Unicode escape sequence");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
                        int unicode = Integer.parseInt(hex, 16);
                        output.append((char) unicode);
                        i += 4; // Move past the hex digits
                    } catch (NumberFormatException e) {
                        throw new Exception("Malformed Unicode escape sequence");
                    }
                    break;
                default:
                    throw new Exception("Invalid escape sequence");
            }
        } else {
            output.append(currentChar);
        }
    }
    return output.toString();
}
